#!/usr/bin/env node
/**
 * Regenerates the TypeScript export surface for the lunar package:
 *
 * 1. lunar/index.ts           — re-exports entity interfaces (under their short
 *                               table names), per-enum types and JsonValue.
 * 2. lunar/bindings/index.ts  — barrel re-exporting every binding type.
 * 3. lunar/package.json       — exports map for "./bindings", "./pkg" and
 *                               "./pkg/*", plus the "pkg" entry in "files".
 *
 * Type-to-file mapping is derived deterministically from the Rust sources so the
 * generated files stay correct regardless of when cargo rebuilds the bindings.
 *
 * Usage (from inside lunar/):
 *     node ../scripts/fix-ts-exports.mjs [entities_dir]
 *
 * entities_dir defaults to src/entities.
 */

import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const ENUM_PATTERN = /^pub enum (\w+)/m;
const EXPORT_TO_PATTERN = /#\[ts\([^)]*export_to\s*=\s*"([^"]+)\.ts"\)\]/;
const TYPE_PATTERN = /^pub (?:struct|enum) (\w+)/m;

const SKIP = new Set(["mod", "prelude"]);

// ts-rs (serde-json-impl) emits this file for serde_json::Value.
const JSON_VALUE = ["JsonValue", "serde_json/JsonValue"];

const HEADER = "// Auto-generated by scripts/fix-ts-exports.mjs — do not edit manually.\n";

function toPascal(stem) {
  return stem
    .split("_")
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join("");
}

function readText(path) {
  return readFileSync(path, "utf8");
}

function writeText(path, content) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content, "utf8");
}

function discoverEnums(path) {
  if (!existsSync(path)) return [];
  const names = [];
  for (const line of readText(path).split("\n")) {
    const match = ENUM_PATTERN.exec(line);
    if (match) names.push(match[1]);
  }
  return names.sort();
}

/**
 * Return [typeName, exportToFileStem] pairs for
 * #[ts(export, export_to=...)] structs and enums in a Rust source file.
 */
function discoverTypeExports(path) {
  if (!existsSync(path)) return [];
  const results = [];
  let currentTarget = null;
  for (const line of readText(path).split("\n")) {
    const attr = EXPORT_TO_PATTERN.exec(line);
    if (attr) {
      currentTarget = attr[1];
      continue;
    }
    const type = TYPE_PATTERN.exec(line);
    if (type && currentTarget) {
      results.push([type[1], currentTarget]);
    }
  }
  return results;
}

/** Discover adapter/sync_engine structs exported to bindings, sorted by struct name. */
function discoverActionTypes(root) {
  const sources = [];
  const adaptersDirs = [
    join(root, "src", "adapters"),
    join(root, "..", "server", "src", "adapters"),
  ];
  for (const adaptersDir of adaptersDirs) {
    if (existsSync(adaptersDir)) {
      for (const entry of readdirSync(adaptersDir).sort()) {
        if (entry.endsWith(".rs")) sources.push(join(adaptersDir, entry));
      }
    }
  }
  const syncEngine = join(root, "src", "sync_engine.rs");
  if (existsSync(syncEngine)) sources.push(syncEngine);

  const types = new Map();
  for (const source of sources) {
    for (const [name, target] of discoverTypeExports(source)) {
      if (!types.has(name)) types.set(name, target);
    }
  }
  return [...types.entries()].sort();
}

/** Map every exported binding type name to its bindings-relative module path. */
function collectBindings(entitiesDir, root) {
  const bindings = new Map();
  const setDefault = (name, modulePath) => {
    if (!bindings.has(name)) bindings.set(name, modulePath);
  };

  for (const entry of readdirSync(entitiesDir).sort()) {
    if (!entry.endsWith(".rs")) continue;
    const stem = entry.slice(0, -3);
    if (SKIP.has(stem)) continue;

    if (stem === "sea_orm_active_enums") {
      for (const name of discoverEnums(join(entitiesDir, entry))) {
        setDefault(name, name);
      }
    } else {
      const name = toPascal(stem) + "Interface";
      setDefault(name, name);
    }
  }

  for (const [name, target] of discoverActionTypes(root)) {
    setDefault(name, target);
  }

  setDefault(JSON_VALUE[0], JSON_VALUE[1]);

  return bindings;
}

function generateBindingsBarrel(entitiesDir, root) {
  const bindings = collectBindings(entitiesDir, root);
  const exports = [...bindings.entries()]
    .sort()
    .map(([name, modulePath]) => `export type { ${name} } from "./${modulePath}";\n`);

  const barrelPath = "bindings/index.ts";
  writeText(barrelPath, HEADER + "\n" + exports.join(""));
  console.log(`  wrote: ${barrelPath} (${exports.length} type exports)`);
}

function generateIndex(entitiesDir, root) {
  const specialExports = [];
  const aliases = [];
  const actionExports = [];

  for (const entry of readdirSync(entitiesDir).sort()) {
    if (!entry.endsWith(".rs")) continue;
    const stem = entry.slice(0, -3);
    if (SKIP.has(stem)) continue;

    if (stem === "sea_orm_active_enums") {
      for (const name of discoverEnums(join(entitiesDir, entry))) {
        specialExports.push(`export type { ${name} } from "./bindings/${name}";\n`);
      }
    } else {
      const typeName = toPascal(stem) + "Interface";
      const shortName = toPascal(stem);
      aliases.push(`export type { ${typeName} as ${shortName} } from "./bindings/${typeName}";\n`);
    }
  }

  specialExports.push(`export type { ${JSON_VALUE[0]} } from "./bindings/${JSON_VALUE[1]}";\n`);

  const emitted = new Set(
    [...specialExports, ...aliases].map((line) => /export type \{ (\w+)/.exec(line)[1]),
  );
  for (const [name, target] of discoverActionTypes(root)) {
    if (emitted.has(name)) continue;
    actionExports.push(`export type { ${name} } from "./bindings/${target}";\n`);
  }

  const indexPath = "index.ts";
  writeText(indexPath, HEADER + specialExports.join("") + "\n" + aliases.join("") + "\n" + actionExports.join(""));
  console.log(
    `  wrote: ${indexPath} (${specialExports.length} special exports, ${aliases.length} interface aliases, ${actionExports.length} action exports)`,
  );
}

function updatePackageJson() {
  const pkgPath = "package.json";
  const data = JSON.parse(readText(pkgPath));

  data.exports = {
    ".": { types: "./index.ts" },
    "./index": { types: "./index.ts" },
    "./bindings": { types: "./bindings/index.ts" },
    "./pkg": "./pkg/lunar.js",
    "./pkg/*": "./pkg/*",
  };

  const files = new Set(data.files ?? []);
  for (const entry of ["index.ts", "bindings", "pkg"]) files.add(entry);
  data.files = [...files];

  writeFileSync(pkgPath, JSON.stringify(data, null, 2) + "\n", "utf8");
  console.log(`  wrote: ${pkgPath} (exports + files)`);
}

function main() {
  const entitiesDir = process.argv[2] ?? "src/entities";

  if (!existsSync(entitiesDir)) {
    console.error(`error: directory not found: ${entitiesDir}`);
    process.exit(1);
  }

  const root = process.cwd();

  generateBindingsBarrel(entitiesDir, root);
  generateIndex(entitiesDir, root);
  updatePackageJson();
}

main();
